model:
rachana: 1
sutra: cap-vol-surface
version: 2
description: 
match: { kind: cap-vol-surface, priority: 10 }
title: { pill: "Market data · Cap/floor volatility surface", id: "$.SURFACE_ID" }
strip:
  - { label: "Currency", bind: "$.CURRENCY" }
  - { label: "5Y ATM", bind: "$.ATM_5Y", fmt: "price2", emphasis: true }
panels:
  - id: surface
    kind: surface
    title: "Cap vols by maturity × strike (bp)"
    key: "F4"
    code: "SURF"
    rows: "$.GRID"
    y: "MATURITY"
    columns:
      - { label: "ATM", bind: "@.ATM", fmt: "price2" }
      - { label: "2%", bind: "@.K_2", fmt: "price2" }
      - { label: "3%", bind: "@.K_3", fmt: "price2" }
      - { label: "4%", bind: "@.K_4", fmt: "price2" }
      - { label: "5%", bind: "@.K_5", fmt: "price2" }
  - id: grid
    kind: table
    title: "Cap vols (bp)"
    key: "F2"
    rows: "$.GRID"
    columns:
      - { label: "Maturity", bind: "@.MATURITY" }
      - { label: "ATM", bind: "@.ATM", fmt: "price2" }
      - { label: "2%", bind: "@.K_2", fmt: "price2" }
      - { label: "3%", bind: "@.K_3", fmt: "price2" }
      - { label: "4%", bind: "@.K_4", fmt: "price2" }
      - { label: "5%", bind: "@.K_5", fmt: "price2" }
  - id: atm
    kind: line
    title: "ATM by maturity"
    area: right
    rows: "$.GRID"
    x: "MATURITY"
    y: "ATM"
    fmt: "price2"
  - id: built
    kind: provenance
    title: "How this view was built"
keys: { F8: "impact", F9: "raw" }
